export interface GalaxyMovie {
  id: string;
  name: string;
  age: string;
  duration: number;
  startDate: string;
  endDate: string;
  createdAt: string;
  imageLandscape: string;
  imagePortrait: string;
  slug: string;
  trailer: string;
  rate: number;
  totalVotes: number;
  views: number;
  order: number;
}

export interface GalaxyCinema {
  id: string;
  code: string;
  name: string;
  latitude: string;
  longitude: string;
  address: string;
  phone: string;
  cityId: string;
  imageLandscape: string;
  imagePortrait: string;
  imageUrls: string[];
  order: number;
}

export interface GalaxySession {
  id: string;
  showDate: string;
  showTime: string;
  screenName: string;
  totalSeat: number;
  bookedSeat: number;
  caption: 'voice' | 'sub' | string;
  version: '2d' | '3d' | 'imax' | string;
  movieFormat: string;
  movie: GalaxyMovie;
  cinema: GalaxyCinema;
}

export interface GalaxyApiResponse {
  response: {
    status: number;
    code: number;
    message: string;
    url: string;
  };
  data: {
    total: number;
    result: GalaxySession[];
  };
}

